import React, { useEffect, useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import { useNavigate } from "react-router-dom";
import API_BASE_URL from "../config";
import "../App.css";

const MyListings = () => {
  const navigate = useNavigate();
  const userId = sessionStorage.getItem("userId");
  const [listings, setListings] = useState([]);

  useEffect(() => {
    if (userId) {
      fetch(`${API_BASE_URL}/api/listings/user/${userId}`)
        .then((res) => res.json())
        .then((data) => setListings(data))
        .catch((err) => console.error("Error fetching listings:", err));
    }
  }, [userId]);

  return (
    <div className="dashboard-wrapper">
      <Navbar />
      <main className="mylistings-main">
        <div className="sidebar-fixed">
          <h3 className="sidebar-title">My Listings</h3>
          <button className="sidebar-btn" onClick={() => navigate("/create-listing")}>Create Listing</button>
        </div>

        <div className="listing-grid">
          {listings.length > 0 ? (
            listings.map((item) => (
              <div className="listing-card" key={item.id}>
                <img src={item.image} alt={item.title} className="listing-img" />
                <div className="listing-info">
                  <h4>{item.title}</h4>
                  <p>{item.description}</p>
                  <p><strong>Category:</strong> {item.category}</p>
                  <p><strong>Condition:</strong> {item.condition}</p>
                  <p><strong>Price:</strong> ${parseFloat(item.price).toFixed(2)}</p>
                  <p><strong>Status:</strong> {item.sold ? "SOLD" : "Available"}</p>
                  <button
                    className="edit-btn"
                    onClick={() => navigate(`/edit-listing/${item.id}`)}
                  >
                    Edit
                  </button>
                </div>
              </div>
            ))
          ) : (
            <p className="no-listings-text">You haven’t listed anything yet.</p>
          )}
        </div>
      </main>
      <Footer />
    </div>
  );
};

export default MyListings;
